import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { formatCurrency, formatDate } from '@/lib/utils';
import { 
  AdjustmentsHorizontalIcon, 
  PlusIcon, 
  MagnifyingGlassIcon,
  ExclamationTriangleIcon,
  ArrowDownTrayIcon,
  ArrowUpTrayIcon,
  ArrowPathIcon
} from '@heroicons/react/24/outline';
import apiClient, { endpoints } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';

// Types
interface InventoryItem {
  id: string;
  sku: string;
  name: string;
  category: string;
  current_stock: number;
  min_stock_level: number;
  cost: number;
  price: number;
  updated_at: string;
}

export default function InventoryPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [categories, setCategories] = useState<string[]>(['All']);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [stockStatus, setStockStatus] = useState('All');
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await apiClient.get(endpoints.products);
      const prods = response.data || [];
      
      // Map products to inventory structure
      // Note: Real API might need a separate call for current_stock per branch, 
      // but we'll use product metadata as baseline for now or assume simple 1-to-1 if stock is in product.
      const items: InventoryItem[] = prods.map((p: any) => ({
        id: p.id,
        sku: p.sku,
        name: p.name,
        category: p.category,
        current_stock: p.current_stock || 0, // Fallback if not provided directly
        min_stock_level: p.min_stock_level || 0,
        cost: p.cost || 0,
        price: p.price || 0,
        updated_at: p.updated_at
      }));

      setInventory(items);
      
      const cats = ['All', ...new Set(items.map(item => item.category))];
      setCategories(cats);
      setLoading(false);
    } catch (err) {
      console.error('Inventory fetch error:', err);
      setError('Failed to load inventory data.');
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const getStockStatus = (item: InventoryItem) => {
    if (item.current_stock === 0) return 'Out of Stock';
    if (item.current_stock <= item.min_stock_level) return 'Low Stock';
    return 'In Stock';
  };

  const getStockStatusVariant = (status: string): 'success' | 'warning' | 'error' | 'default' => {
    switch (status) {
      case 'In Stock': return 'success';
      case 'Low Stock': return 'warning';
      case 'Out of Stock': return 'error';
      default: return 'default';
    }
  };

  const filteredInventory = inventory.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                         item.sku.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || item.category === selectedCategory;
    const itemStatus = getStockStatus(item);
    const matchesStatus = stockStatus === 'All' || itemStatus === stockStatus;
    return matchesSearch && matchesCategory && matchesStatus;
  });

  const lowStockItems = inventory.filter(item => item.current_stock > 0 && item.current_stock <= item.min_stock_level);
  const outOfStockItems = inventory.filter(item => item.current_stock === 0);

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Inventory Header */}
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <div>
              <h1 className="text-2xl font-bold text-primary">Inventory Management</h1>
              <p className="mt-1 text-sm text-text-secondary">Track stock levels and manage inventory items</p>
            </div>
            <div className="flex gap-2 w-full sm:w-auto">
              <Button variant="outline" size="sm" onClick={fetchData} disabled={loading}>
                <ArrowPathIcon className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                Refresh
              </Button>
              <Button>
                <ArrowUpTrayIcon className="h-4 w-4 mr-2" />
                Export
              </Button>
              <Button onClick={() => window.location.href = '/products'}>
                <PlusIcon className="h-4 w-4 mr-2" />
                Manage Products
              </Button>
            </div>
          </div>

          {/* Inventory Stats */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-primary/10 rounded-lg">
                  <AdjustmentsHorizontalIcon className="h-6 w-6 text-primary" />
                </div>
                <div className="ml-4">
                  <p className="text-xs font-bold text-text-secondary uppercase tracking-wider">Total Items</p>
                  <p className="text-2xl font-black text-primary">{inventory.length}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6 border-l-4 border-warning">
              <div className="flex items-center">
                <div className="p-3 bg-warning/10 rounded-lg">
                  <ExclamationTriangleIcon className="h-6 w-6 text-warning" />
                </div>
                <div className="ml-4">
                  <p className="text-xs font-bold text-text-secondary uppercase tracking-wider">Low Stock</p>
                  <p className="text-2xl font-black text-warning">{lowStockItems.length}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6 border-l-4 border-error">
              <div className="flex items-center">
                <div className="p-3 bg-error/10 rounded-lg">
                  <ExclamationTriangleIcon className="h-6 w-6 text-error" />
                </div>
                <div className="ml-4">
                  <p className="text-xs font-bold text-text-secondary uppercase tracking-wider">Out of Stock</p>
                  <p className="text-2xl font-black text-error">{outOfStockItems.length}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Search and Filters */}
          <div className="card p-4">
            <div className="flex flex-col lg:flex-row gap-4">
              <div className="flex-1">
                <div className="relative">
                  <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-text-secondary" />
                  <Input
                    placeholder="Search by name or SKU..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10 h-10"
                  />
                </div>
              </div>
              <div className="flex gap-2">
                <select
                  value={selectedCategory}
                  onChange={(e) => setSelectedCategory(e.target.value)}
                  className="bg-surface border border-divider rounded-lg px-3 py-2 text-sm font-bold text-primary focus:ring-1 focus:ring-primary"
                >
                  {categories.map(category => (
                    <option key={category} value={category}>{category}</option>
                  ))}
                </select>
                <select
                  value={stockStatus}
                  onChange={(e) => setStockStatus(e.target.value)}
                  className="bg-surface border border-divider rounded-lg px-3 py-2 text-sm font-bold text-primary focus:ring-1 focus:ring-primary"
                >
                  <option value="All">All Statuses</option>
                  <option value="In Stock">In Stock</option>
                  <option value="Low Stock">Low Stock</option>
                  <option value="Out of Stock">Out of Stock</option>
                </select>
              </div>
            </div>
          </div>

          {/* Error State */}
          {error && (
            <div className="bg-error-light border border-error/20 rounded-lg p-4 flex items-center justify-between">
              <p className="text-error text-sm">{error}</p>
              <Button variant="outline" size="sm" onClick={fetchData}>Retry</Button>
            </div>
          )}

          {/* Inventory Table */}
          <div className="card overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full divide-y divide-divider">
                <thead className="bg-surface">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider">SKU</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider">Product</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider">Category</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider text-center">In Stock</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider text-center">Min Level</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider">Unit Cost</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider">Unit Price</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-text-secondary uppercase tracking-wider">Status</th>
                  </tr>
                </thead>
                <tbody className="bg-card divide-y divide-divider">
                  {loading ? (
                    [...Array(5)].map((_, i) => (
                      <tr key={i} className="animate-pulse">
                        <td colSpan={8} className="px-6 py-4">
                          <div className="h-10 bg-surface rounded w-full"></div>
                        </td>
                      </tr>
                    ))
                  ) : filteredInventory.length > 0 ? (
                    filteredInventory.map(item => {
                      const status = getStockStatus(item);
                      return (
                        <tr key={item.id} className="hover:bg-surface transition-colors cursor-pointer">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-primary">{item.sku}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-primary font-medium">{item.name}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-text-secondary uppercase font-bold text-[10px]">{item.category}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-black text-center text-primary">
                            {item.current_stock}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-text-secondary text-center">
                            {item.min_stock_level}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-primary">{formatCurrency(item.cost)}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-primary">{formatCurrency(item.price)}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm">
                            <Badge variant={getStockStatusVariant(status)}>
                              {status}
                            </Badge>
                          </td>
                        </tr>
                      );
                    })
                  ) : (
                    <tr>
                      <td colSpan={8} className="px-6 py-12 text-center text-text-secondary bg-surface/30">
                        <AdjustmentsHorizontalIcon className="h-12 w-12 mx-auto mb-4 opacity-20" />
                        <p>No inventory items found matching your filters</p>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
